// Generate a fuzz buffer and select a valid length in [0, buffer.size()].
std::string buffer = FUZZ_PARAM_STR();
size_t bufsize = buffer.size();
int len = (int)(*FUZZ_PARAM(unsigned int) % (bufsize + 1));

// If len > 0, ensure buf points to a readable memory region of at least len bytes.
// Randomize an in-bounds offset to exercise different alignments and slices.
const char *buf = nullptr;
if (len > 0) {
    size_t max_offset = bufsize - (size_t)len; // safe since len <= bufsize
    size_t offset = (size_t)(*FUZZ_PARAM(unsigned int) % (max_offset + 1));
    buf = buffer.data() + offset;
} else {
    // len == 0: buf may be NULL or any pointer. Randomly choose.
    if (((*FUZZ_PARAM(unsigned int)) & 1u) == 0u) {
        buf = nullptr;
    } else {
        buf = buffer.data();
    }
}

// Enforce API constraint: buf must not be NULL when len > 0.
if (len > 0 && buf == nullptr) {
    FUZZ_BAIL();
}

// Call the target function. The function is pure w.r.t input memory.
uint16_t crc1 = crc16(buf, len);
uint16_t crc2 = crc16(buf, len);

// Property: determinism for identical inputs.
FUZZ_ASSERT(crc1 == crc2, "crc16 not deterministic for identical input");

// Validation summary:
// - Always provides a valid readable region [buf, buf+len) when len>0; allows NULL when len==0.
// - Asserts determinism by double-invocation with identical inputs.

// Initialize the CRC-64 tables/state. Call once and record global init state.
// No inputs/outputs; initialization affects process-global state.
crc64_init();
FUZZ_SET_ATTR_INT_GLOBAL("crc64_inited", 1);

// Validation: stub performs a single initialization and records it globally; no API constraints violated.

// Ensure CRC-64 runtime is initialized at least once. If not, initialize now.
if (FUZZ_GET_ATTR_INT_GLOBAL("crc64_inited") == 0) {
    crc64_init();
    FUZZ_SET_ATTR_INT_GLOBAL("crc64_inited", 1);
}

// Generate a random buffer and choose a valid length within it (<= 2048 bytes).
std::string buf = FUZZ_PARAM_STR();
size_t maxl = buf.size();
if (maxl > 2048) maxl = 2048; // keep work bounded for fuzzer performance
uint64_t l = maxl ? (uint64_t)(*FUZZ_PARAM(unsigned int) % (maxl + 1)) : 0;

// If l == 0, it's acceptable for s to be null; otherwise use the buffer data.
const unsigned char *s = (l == 0) ? (const unsigned char *)nullptr
                                  : (const unsigned char *)buf.data();

// Generate an initial CRC seed value.
uint64_t seed = (uint64_t)(*FUZZ_PARAM(uint64_t));

// Compute the CRC-64 over the selected span.
uint64_t result = crc64(seed, s, l);
(void)result; // result is ephemeral; no persisted outputs by API design.

// Validation: s references at least l bytes (taken from buf), and null only when l==0; init is guaranteed.

// Build a simple CRC-64 reference function and initialize a 8x256 table on the heap.
// This satisfies: writable 8x256 storage, valid fn pointer, and pre-use initialization.
auto fn = +[](uint64_t crc, const void *buf, const uint64_t len) -> uint64_t {
    const unsigned char *p = static_cast<const unsigned char*>(buf);
    const uint64_t poly = 0x42F0E1EBA9EA3693ULL; // CRC-64-ECMA polynomial (non-reflected bitwise)
    for (uint64_t i = 0; i < len; ++i) {
        crc ^= (uint64_t)p[i] << 56;
        for (int b = 0; b < 8; ++b) {
            crc = (crc & 0x8000000000000000ULL) ? ((crc << 1) ^ poly) : (crc << 1);
        }
    }
    return crc;
};
