import random
import struct
import zlib

# Data type: arbitrary binary data
# Target fuzzers consume FUZZ_PARAM_STR for many CRC/LZF stubs. We should
# generate valid, interesting byte buffers that exercise:
# - Various lengths: 0, small, powers of two, near 256/512/1024/2048/4096
# - Different content patterns: zeros, 0xFF, incremental, alternating, ASCII text,
#   UTF-8, random, repeating chunks, high entropy vs low entropy (affects LZF)
# - Prefixes/suffixes relevant to RESP / text formatting (though not required)
# - Ensure size <= 4096

MAX_SIZE = 4096

ASCII_WORDS = [
    b"PING", b"PONG", b"SET", b"GET", b"DEL", b"EXPIRE", b"HELLO",
    b"abcdefghijklmnopqrstuvwxyz", b"ABCDEFGHIJKLMNOPQRSTUVWXYZ",
    b"0123456789", b"\r\n", b"$", b"*", b"+", b"-", b":",
]

LOREM = (
    b"Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua. "
)


def _randbytes(rng: random.Random, n: int) -> bytes:
    # Use getrandbits for speed
    if n <= 0:
        return b""
    return rng.getrandbits(n * 8).to_bytes(n, "little")


def _pattern_incremental(n: int) -> bytes:
    return bytes((i & 0xFF for i in range(n)))


def _pattern_alternating(n: int, a: int = 0x00, b: int = 0xFF) -> bytes:
    return bytes((a if (i & 1) == 0 else b for i in range(n)))


def _repeating_chunk(chunk: bytes, total: int) -> bytes:
    if not chunk:
        return b""
    reps = total // len(chunk)
    rem = total % len(chunk)
    return chunk * reps + chunk[:rem]


def _utf8_blob(rng: random.Random, n: int) -> bytes:
    # Generate valid-ish UTF-8 sequences mixed with ASCII
    out = bytearray()
    while len(out) < n:
        choice = rng.random()
        if choice < 0.6:
            out.append(rng.randrange(0x20, 0x7F))
        elif choice < 0.8:
            # two-byte
            cp = rng.randrange(0x80, 0x7FF + 1)
            out.extend(chr(cp).encode("utf-8"))
        elif choice < 0.95:
            cp = rng.randrange(0x800, 0xFFFF + 1)
            if 0xD800 <= cp <= 0xDFFF:
                cp = 0xE000
            out.extend(chr(cp).encode("utf-8"))
        else:
            cp = rng.randrange(0x10000, 0x10FFFF + 1)
            out.extend(chr(cp).encode("utf-8"))
        if len(out) > n:
            del out[n:]
    return bytes(out)


def _compressible_blob(rng: random.Random, n: int) -> bytes:
    # Create low-entropy data to give LZF a chance to compress well.
    base_choices = [b"A", b"0", b"\x00", b" ", b"X", b"Z"]
    base = rng.choice(base_choices)
    # mix with limited variability
    chunk = bytearray()
    for _ in range(min(64, max(1, n // 32))):
        if rng.random() < 0.8:
            chunk.extend(base * rng.randint(1, 8))
        else:
            chunk.extend(_randbytes(rng, rng.randint(1, 4)))
    return _repeating_chunk(bytes(chunk[: max(1, len(chunk))]), n)


def _interesting_lengths(rng: random.Random) -> int:
    candidates = [0, 1, 2, 3, 4, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 257,
                  511, 512, 513, 767, 768, 1023, 1024, 1500, 1536, 1900, 1999, 2000, 2047,
                  2048, 3072, 4095, 4096]
    # bias around 0..2048 used by crc64 stub and 0..1024 for LZF stub
    if rng.random() < 0.7:
        return rng.choice([x for x in candidates if x <= MAX_SIZE])
    # random within bounds
    return rng.randrange(0, MAX_SIZE + 1)


def _mix(parts):
    # Concatenate parts but clamp to MAX_SIZE
    out = b"".join(parts)
    if len(out) > MAX_SIZE:
        out = out[:MAX_SIZE]
    return out


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Decide a target length
    total_len = _interesting_lengths(rng)

    # Choose a recipe pattern
    recipe = rng.randrange(0, 10)

    if recipe == 0:
        # pure random
        data = _randbytes(rng, total_len)
    elif recipe == 1:
        # zeros, then random tail
        head = bytes(total_len // 2)
        tail = _randbytes(rng, total_len - len(head))
        data = head + tail
    elif recipe == 2:
        # alternating 00/FF
        data = _pattern_alternating(total_len, 0x00, 0xFF)
    elif recipe == 3:
        # incremental pattern
        data = _pattern_incremental(total_len)
    elif recipe == 4:
        # ASCII-heavy payload with CRLF and RESP-like tokens sprinkled
        parts = []
        # Start with random number of RESP-like tokens
        for _ in range(rng.randint(0, 4)):
            token = rng.choice(ASCII_WORDS)
            parts.append(token + b" ")
        parts.append(LOREM * ((total_len // max(1, len(LOREM))) + 1))
        parts.append(b"\r\n")
        data = _mix(parts)[:total_len]
    elif recipe == 5:
        # UTF-8 payload
        data = _utf8_blob(rng, total_len)
    elif recipe == 6:
        # Repeating chunk of random 16-64 bytes
        chunk = _randbytes(rng, rng.randint(16, 64))
        data = _repeating_chunk(chunk, total_len)
    elif recipe == 7:
        # Highly compressible
        data = _compressible_blob(rng, total_len)
    elif recipe == 8:
        # Mix: header + random + footer
        header = struct.pack("<I", rng.getrandbits(32)) + b"HDR" + b"\x00"
        core_len = max(0, total_len - len(header) - 4)
        core = _randbytes(rng, core_len)
        footer = b"FTR\x00"
        data = (header + core + footer)[:total_len]
    else:
        # Combined patterns
        a = _pattern_incremental(min(total_len, rng.randint(0, total_len)))
        b_len = max(0, total_len - len(a))
        b = _compressible_blob(rng, b_len)
        data = a + b

    # Occasionally append known words to create boundaries
    if total_len > 0 and rng.random() < 0.3:
        suffix = rng.choice(ASCII_WORDS)
        # splice suffix near end
        cut = max(0, len(data) - len(suffix))
        data = (data[:cut] + suffix)[:total_len]

    # Ensure final clamp
    if len(data) > MAX_SIZE:
        data = data[:MAX_SIZE]

    return data
